    ctx.textBaseline = "middle";
    const ticks = 4;
    for (let i = 0; i <= ticks; i++) {
      const v = min + (range * i) / ticks;
      const y = padT + plotH - (plotH * i) / ticks;
      ctx.strokeStyle = "rgba(148,163,184,0.25)";
